  let t = 0;
  let particles = [];
  let bgImg = null;

  controls.onChange('background', function(url) {
    if (!url) { bgImg = null; return; }
    var img = new Image();
    img.crossOrigin = 'anonymous';
    img.onload = function() { bgImg = img; };
    img.src = url;
  });

  function spawnParticles(count) {
    for (let i = 0; i < count; i++) {
      particles.push({
        x: canvas.width / 2,
        y: canvas.height / 2,
        vx: (Math.random() - 0.5) * 4,
        vy: (Math.random() - 0.5) * 4,
        life: 1,
      });
    }
  }

  controls.onAction('reset', function() {
    t = 0;
    particles = [];
    spawnParticles(30);
  });

  spawnParticles(30);

  function draw() {
    var w = canvas.width;
    var h = canvas.height;
    var speed = controls.get('speed') / 50;
    var size = controls.get('size');
    var animate = controls.get('animate');
    var color = typeof controls.getColorWithAlpha === 'function'
      ? controls.getColorWithAlpha('color')
      : controls.get('color');
    var shape = controls.get('shape');
    var title = controls.get('title');

    if (animate) t += 0.02 * speed;

    if (bgImg) {
      ctx.drawImage(bgImg, 0, 0, w, h);
    } else {
      ctx.fillStyle = '#0a0a0a';
      ctx.fillRect(0, 0, w, h);
    }

    // Draw center shape
    ctx.save();
    ctx.translate(w / 2, h / 2);
    var baseSize = 40 * size;
    var pulse = 1 + Math.sin(t * 3) * 0.1;
    var s = baseSize * pulse;

    ctx.fillStyle = color;
    ctx.globalAlpha = 1;

    if (shape === 'circle') {
      ctx.beginPath();
      ctx.arc(0, 0, s, 0, Math.PI * 2);
      ctx.fill();
    } else if (shape === 'square') {
      ctx.fillRect(-s, -s, s * 2, s * 2);
    } else if (shape === 'triangle') {
      ctx.beginPath();
      ctx.moveTo(0, -s);
      ctx.lineTo(s, s);
      ctx.lineTo(-s, s);
      ctx.closePath();
      ctx.fill();
    }
    ctx.restore();

    // Draw particles
    ctx.globalAlpha = 1;
    for (var i = particles.length - 1; i >= 0; i--) {
      var p = particles[i];
      if (animate) {
        p.x += p.vx * speed;
        p.y += p.vy * speed;
        p.life -= 0.003 * speed;
      }
      if (p.life <= 0) {
        p.x = w / 2;
        p.y = h / 2;
        p.vx = (Math.random() - 0.5) * 4;
        p.vy = (Math.random() - 0.5) * 4;
        p.life = 1;
      }
      ctx.globalAlpha = p.life * 0.6;
      ctx.fillStyle = typeof controls.getColorWithAlpha === 'function'
        ? controls.getColorWithAlpha('color')
        : controls.get('color');
      ctx.beginPath();
      ctx.arc(p.x, p.y, 2 * size, 0, Math.PI * 2);
      ctx.fill();
    }

    // Draw title text
    ctx.globalAlpha = 0.7;
    ctx.fillStyle = '#e0e0e0';
    ctx.font = (14 * size) + 'px system-ui, sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText(title || '', w / 2, h / 2 + baseSize + 30);

    ctx.globalAlpha = 1;
    requestAnimationFrame(draw);
  }
  draw();
